import{_ as r,c as a,o as t,ag as i}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"OSCP","description":"","frontmatter":{"title":"OSCP"},"headers":[],"relativePath":"cybersecurity/oscp.md","filePath":"cybersecurity/oscp.md","lastUpdated":null}'),o={name:"cybersecurity/oscp.md"};function l(s,e,n,c,h,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="oscp" tabindex="-1">OSCP <a class="header-anchor" href="#oscp" aria-label="Permalink to &quot;OSCP&quot;">​</a></h1><h2 id="pen-200-penetration-testing-with-kali-linux-oscp" tabindex="-1">PEN-200: Penetration Testing with Kali Linux (OSCP) <a class="header-anchor" href="#pen-200-penetration-testing-with-kali-linux-oscp" aria-label="Permalink to &quot;PEN-200: Penetration Testing with Kali Linux (OSCP)&quot;">​</a></h2><p>The OSCP Links &amp; Resources page is a curated collection for those preparing for the OSCP exam. It includes practice resources, Active Directory resources, mind maps, privilege escalation resources, and tools for penetration testing. Additionally, there are links to Red Team GitHub repositories and guides for building labs for practice. The page also provides Techniques for upgrading semi-interactive shells.</p><p>Join the <a href="https://forum.irregularchat.com/t/community-links-to-chats-and-services/229#p-598-tech-8" target="_blank" rel="noreferrer">Certs IrregularChat</a> (Login Required)</p><h3 id="community-feedback" tabindex="-1">Community Feedback <a class="header-anchor" href="#community-feedback" aria-label="Permalink to &quot;Community Feedback&quot;">​</a></h3><p>Sharing experiences and insights from those who have taken the OSCP exam can be incredibly valuable. Below are some comments from the community:</p><ul><li><p><strong>&quot;OSCP was recommended to help round out my resume as a new cyber officer. I started ethical hacking way before joining cyber, so I do enjoy it. The likelihood of me using this skill in a working environment is low. I just personally care about being a technically competent leader.&quot;</strong></p></li><li><p><strong>&quot;I&#39;m going to go out on a limb here and offer a different approach, but it is situational dependent. Why are you taking the OSCP exam? If you just want the cert, read and apply the recommendations above. If you plan to employ the skills/knowledge, I have a much different recommendation: to do the CPTS pipeline.&quot;</strong></p></li><li><p><strong>&quot;I would also recommend setting up a repo of notes/cheat sheets in Obsidian. I also automated my initial Nmap scan process and website enumeration and created global variables of the IPs and URLs with bash scripts I built.&quot;</strong></p></li><li><p><strong>&quot;Got my OSCP on my second attempt. My first attempt was pre-AD, and I bombed it, only 10 points. On my second attempt, I did the Learn One and still only used about 5 months of it because I was deployed during half of it.&quot;</strong></p></li></ul><h3 id="more-resources" tabindex="-1">More Resources <a class="header-anchor" href="#more-resources" aria-label="Permalink to &quot;More Resources&quot;">​</a></h3><h3 id="practice-resources" tabindex="-1">Practice Resources <a class="header-anchor" href="#practice-resources" aria-label="Permalink to &quot;Practice Resources&quot;">​</a></h3><p>Link links to practice labs, challenges, and other resources to help you hone your skills.</p><ul><li><p><a href="https://docs.google.com/spreadsheets/u/1/d/1dwSMIAPIam0PuRBkCiDI88pU3yzrqqHkDtBngUHNCw8/htmlview" target="_blank" rel="noreferrer">NetSecFocus &quot;TJ Null&#39;s&quot; Trophy Room (Google Sheet)</a></p></li><li><p><a href="https://oscp.infosecsanyam.in/" target="_blank" rel="noreferrer">All About OSCP</a></p></li><li><p><a href="https://www.netsecfocus.com/oscp/2019/03/29/The_Journey_to_Try_Harder-_TJNulls_Preparation_Guide_for_PWK_OSCP.html" target="_blank" rel="noreferrer">TJNull&#39;s Preparation Guide for PWK/OSCP</a></p></li><li><p><a href="https://jaiguptanick.medium.com/oscp-cracking-the-new-pattern-6c4f1c9e2409" target="_blank" rel="noreferrer">Cracking the New Pattern</a></p></li><li><p><a href="https://www.reddit.com/r/oscp/comments/k7x4o1/just_passed_oscpmy_journey_and_tips/" target="_blank" rel="noreferrer">Reddit OSCP Journey and Tips</a></p></li><li><p><a href="https://robertscocca.medium.com/avoiding-common-oscp-pitfalls-d2dd929fdb03" target="_blank" rel="noreferrer">Avoiding Common OSCP Pitfalls</a></p></li><li><p><a href="https://sushant747.gitbooks.io/total-oscp-guide/content/" target="_blank" rel="noreferrer">Total OSCP Guide</a></p></li><li><p><a href="https://github.com/HackedBaked/OSCP_Scripts" target="_blank" rel="noreferrer">OSCP Scripts</a></p></li><li><p><a href="https://infinitelogins.com/enumeration-cheatsheets/" target="_blank" rel="noreferrer">Enumeration Cheatsheets</a></p></li><li><p><a href="https://trojand.com/cheatsheet/OSCP/General_Cheatsheet.html" target="_blank" rel="noreferrer">General OSCP Cheatsheet</a></p></li></ul><h3 id="active-directory-resources" tabindex="-1">Active Directory Resources <a class="header-anchor" href="#active-directory-resources" aria-label="Permalink to &quot;Active Directory Resources&quot;">​</a></h3><h4 id="purple-team" tabindex="-1">Purple Team <a class="header-anchor" href="#purple-team" aria-label="Permalink to &quot;Purple Team&quot;">​</a></h4><ul><li><p><a href="https://github.com/swisskyrepo/PayloadsAllTheThings/blob/master/Methodology%20and%20Resources/Active%20Directory%20Attack.md" target="_blank" rel="noreferrer">SwisskyRepo - Active Directory Attack</a></p></li><li><p><a href="https://book.hacktricks.xyz/windows-hardening/active-directory-methodology/" target="_blank" rel="noreferrer">HackTricks - AD Methodology</a></p></li></ul><h4 id="red-team" tabindex="-1">Red Team <a class="header-anchor" href="#red-team" aria-label="Permalink to &quot;Red Team&quot;">​</a></h4><ul><li><p><a href="https://github.com/0xJs/CRTP-cheatsheet" target="_blank" rel="noreferrer">GitHub - 0xJs - Certified Red Team Professional Cheatsheet</a></p></li><li><p><a href="https://github.com/0xJs/RedTeaming_CheatSheet/tree/main/windows-ad" target="_blank" rel="noreferrer">GitHub - 0xJs - Red Teaming Cheat Sheet for Windows Active Directory</a></p></li><li><p><a href="https://www.ired.team/offensive-security-experiments/offensive-security-cheetsheets" target="_blank" rel="noreferrer">iRed Team - Offensive Security Experiments - Offensive Security Cheatsheets</a></p></li><li><p><a href="https://zer1t0.gitlab.io/posts/attacking_ad/" target="_blank" rel="noreferrer">Zer1t0&#39;s Blog - Attacking Active Directory</a></p></li><li><p><a href="https://luemmelsec.github.io/S4fuckMe2selfAndUAndU2proxy-A-low-dive-into-Kerberos-delegations/" target="_blank" rel="noreferrer">Lümmelsec - A Low Dive into Kerberos Delegations</a></p></li></ul><h4 id="blue-team" tabindex="-1">Blue Team <a class="header-anchor" href="#blue-team" aria-label="Permalink to &quot;Blue Team&quot;">​</a></h4><ul><li><p><a href="https://wadcoms.github.io/" target="_blank" rel="noreferrer">WADComs - Windows Active Directory Command Line</a></p></li><li><p><a href="https://ldapwiki.com/wiki/Active%20Directory%20Group%20Related%20Searches" target="_blank" rel="noreferrer">AD Group Related Queries</a></p></li><li><p><a href="https://ldapwiki.com/wiki/Active%20Directory%20User%20Related%20Searches" target="_blank" rel="noreferrer">AD User Related Queries</a></p></li></ul><h3 id="mind-maps" tabindex="-1">Mind Maps <a class="header-anchor" href="#mind-maps" aria-label="Permalink to &quot;Mind Maps&quot;">​</a></h3><ul><li><p><a href="https://whimsical.com/target-machine-ip-23aVmgehajqmAvT9cH4q2K" target="_blank" rel="noreferrer">Whimsical - Target Machine Internet Protocol Workflow Mind Map</a></p></li><li><p><a href="https://orange-cyberdefense.github.io/ocd-mindmaps/img/pentest_ad_dark_2023_02.svg" target="_blank" rel="noreferrer">GitHub - Orange Cyber - Penetration Testing Active Directory Mind Map</a></p></li></ul><h3 id="privilege-escalation-resources" tabindex="-1">Privilege Escalation Resources <a class="header-anchor" href="#privilege-escalation-resources" aria-label="Permalink to &quot;Privilege Escalation Resources&quot;">​</a></h3><h4 id="windows-privilege-escalation" tabindex="-1">Windows Privilege Escalation <a class="header-anchor" href="#windows-privilege-escalation" aria-label="Permalink to &quot;Windows Privilege Escalation&quot;">​</a></h4><ul><li><p><a href="https://sushant747.gitbooks.io/total-oscp-guide/content/privilege_escalation_windows.html" target="_blank" rel="noreferrer">Sushant&#39;s Total Offensive Security Certified Professional Guide - Windows Privilege Escalation</a></p></li><li><p><a href="https://github.com/swisskyrepo/PayloadsAllTheThings/blob/master/Methodology%20and%20Resources/Windows%20-%20Privilege%20Escalation.md" target="_blank" rel="noreferrer">Swisskyrepo - Windows - Privesc</a></p></li></ul><h4 id="linux-privilege-escalation" tabindex="-1">Linux Privilege Escalation <a class="header-anchor" href="#linux-privilege-escalation" aria-label="Permalink to &quot;Linux Privilege Escalation&quot;">​</a></h4><ul><li><a href="https://github.com/swisskyrepo/PayloadsAllTheThings/blob/master/Methodology%20and%20Resources/Linux%20-%20Privilege%20Escalation.md" target="_blank" rel="noreferrer">Swisskyrepo - Linux - Privesc</a></li></ul><h3 id="tools-for-penetration-testing" tabindex="-1">Tools for Penetration Testing <a class="header-anchor" href="#tools-for-penetration-testing" aria-label="Permalink to &quot;Tools for Penetration Testing&quot;">​</a></h3><p>A list of essential tools for conducting penetration tests effectively.</p><ul><li><p><a href="https://github.com/maurosoria/dirsearch" target="_blank" rel="noreferrer">Dirsearch</a></p></li><li><p><a href="https://github.com/OJ/gobuster" target="_blank" rel="noreferrer">Gobuster</a></p></li><li><p><a href="https://github.com/epi052/feroxbuster" target="_blank" rel="noreferrer">FeroxBuster</a></p></li></ul><h3 id="red-team-github-repositories" tabindex="-1">Red Team GitHub Repositories <a class="header-anchor" href="#red-team-github-repositories" aria-label="Permalink to &quot;Red Team GitHub Repositories&quot;">​</a></h3><ul><li><p><a href="https://github.com/A0RX/Red-Blueteam-party" target="_blank" rel="noreferrer">A0RX - Red-Blue Team Party</a></p></li><li><p><a href="https://github.com/MantisSTS/RedTeamTools" target="_blank" rel="noreferrer">MantisSTS - Red Team Tools</a></p></li></ul><h3 id="building-labs-for-practice" tabindex="-1">Building Labs for Practice <a class="header-anchor" href="#building-labs-for-practice" aria-label="Permalink to &quot;Building Labs for Practice&quot;">​</a></h3><ul><li><p><a href="https://philkeeble.com/automation/windows/activedirectory/AWS-RedTeam-ADLab-Setup/" target="_blank" rel="noreferrer">Setting up Amazon Web Services Red Team Active Directory Lab</a></p></li><li><p><a href="https://youtu.be/uzqwoufhwyk" target="_blank" rel="noreferrer">SANS Webcast: Building Your Own Super Duper Home Lab</a></p></li></ul><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><p>[Resources]</p>',34)])])}const m=r(o,[["render",l]]);export{d as __pageData,m as default};
